INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(49911, 'Isaiah 44:8', 'Isaiah', 44, 8, 'ای زما خلکو مه وېرېږئ او ډارېږئ مه! ایا نه پوهېږئ تاسو چې د پخوا زمانې نه بیا تر اوسه څه چې پېښ شوي، ما وه کړې پېشګویي د هغو او تاسو یئ زما شاهدان ایا شته دی بل خدای پرته له ما نه؟ نه، زه نه پېژنم بل د پناه ځای او بل خدای!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_8.mp3', '', 1761754199, 1761754199),
(49912, 'Isaiah 44:9', 'Isaiah', 44, 9, 'هغوی چې بتان جوړوي ناپوه او جاهلان دي او په هغو شیانو پورې زړه تړي چې هېڅ ګټه نه لري. هغه څوک چې د دې بتانو عبادت کوي، هغوی نه ویني او نه پوهیږي چې اخر به وشرمیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_9.mp3', '', 1761754199, 1761754199),
(49913, 'Isaiah 44:10', 'Isaiah', 44, 10, 'یو فلزي بت جوړول او بیا ورته د خدای په توګه عبادت کول څه ګټه لري؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_10.mp3', '', 1761754199, 1761754199),
(49914, 'Isaiah 44:11', 'Isaiah', 44, 11, 'ګورئ، هغوی چې د هغه عبادت کوي، وبه شرمیږي. کوم کسبګران چې بتان جوړوي هغوی یوازې انسانان دي، نور هېڅ شی نه دي. هغوی دې راشي او په محکمه کې دې ودریږي. هغوی به ډېر ووېریږي او ټول به وشرمیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_11.mp3', '', 1761754199, 1761754199),
(49915, 'Isaiah 44:12', 'Isaiah', 44, 12, 'اهنګر د فلز یوه ټوټه اخلي او په داش باندې یې ږدي او کار ورباندې کوي. هغه په خپلو قوي مټو هغه فلز په سټک دومره ټکوي چې یو شکل ورنه جوړ شي. کله چې هغه کار کوي، وږی کیږي، خپل زور له لاسه ورکوي او له تندې بې حاله کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_12.mp3', '', 1761754199, 1761754199),
(49916, 'Isaiah 44:13', 'Isaiah', 44, 13, 'نجار د لرګي اندازه اخلي او په هغه باندې یو تصویر وباسي. وروسته د رندې او تېشې سره هغه لرګي توږي او د بت په شکل یې چې د یو ښایسته انسان څېره ولري، جوړوي. بیا یې په خپل کور کې ږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_13.mp3', '', 1761754199, 1761754199),
(49917, 'Isaiah 44:14', 'Isaiah', 44, 14, 'هغه د سبر ونې وهي، یا له ځنګل نه د څېړۍ ونې غوره کوي او پرېږدي چې ونې لویې شي. یا د سروې ونه کري او انتظار کوي چې د باران لاندې هغه لویه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_14.mp3', '', 1761754199, 1761754199),
(49918, 'Isaiah 44:15', 'Isaiah', 44, 15, 'بیا یو سړی د ونو د لرګیو یوه برخه د سوځولو دپاره اخلي. یوه برخه یې د ځان د تودولو او د ډوډۍ د پخولو دپاره کاروي او له پاتې برخې یې خدای جوړوي او سجده ورته کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_15.mp3', '', 1761754199, 1761754199),
(49919, 'Isaiah 44:16', 'Isaiah', 44, 16, 'د لرګیو له یوې برخې اور بلوي. غوښه کبابوي، خوري یې او مړیږي. هغه خپل ځان تودوي او وایي: «څومره ښه اور بلیږي، زه خپل ځان تود احساسوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_16.mp3', '', 1761754199, 1761754199),
(49920, 'Isaiah 44:17', 'Isaiah', 44, 17, 'له پاتې لرګیو بت جوړوي او بیا ورته په سجده شي او عبادت یې کوي. هغه ته دعا کوي او وایي: «ته زما خدای یې، ما وژغوره!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_17.mp3', '', 1761754199, 1761754199),
(49921, 'Isaiah 44:18', 'Isaiah', 44, 18, 'داسې خلک جاهلان دي او شعور نه لري. د هغوی په سترګو او زړونو پرده پرته ده، نو په دې خاطر هغوی نه ویني او نه پوهیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_18.mp3', '', 1761754199, 1761754199),
(49922, 'Isaiah 44:19', 'Isaiah', 44, 19, 'د بتانو جوړوونکي دومره عقل او شعور نه لري چې فکر وکړي او خپل ځان ته ووایي: «یو څه لرګي مې وسوځول، په هغو باندې مې ډوډۍ پخه کړه، غوښه مې ورباندې کباب کړه او ومې خوړله. اوس څنګه کېدای شي چې د پاتې لرګیو نه یو کرغېړن بت جوړ کړم؟ ایا د لرګي یوې ټوټې ته زه سجده وکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_19.mp3', '', 1761754199, 1761754199),
(49923, 'Isaiah 44:20', 'Isaiah', 44, 20, 'څوک چې بت جوړوي دا داسې دی لکه څوک چې ایرې خوري. د هغه احمقانه فکر هغه داسې بې لارې کړی دی چې له دې فکره ځان نه شي خلاصولی. هغه دا نه شي منلی کوم بت چې د هغه په لاس کې دی، هغه په رښتیا خدای نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_20.mp3', '', 1761754199, 1761754199),
(49924, 'Isaiah 44:21', 'Isaiah', 44, 21, 'څښتن وایي: «ای یعقوبه، په یاد ساته ته دا خبرې: ای اسراییله، په یاد ساته چې ته یې زما خدمتګار ما پیدا کړی یې د دې دپاره چې اوسې زما خدمتګار ای اسراییله، نه هېرومه تا زه هېڅکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_21.mp3', '', 1761754199, 1761754199),
(49925, 'Isaiah 44:22', 'Isaiah', 44, 22, 'سرغړونې مې کړې ستاسو داسې پاکې لکه ورېځې چې ورکیږي له اسمانه ګناهونه مې کړل پاک ستاسو لکه غبار په شان چې ورکوي یې لمر راستانه شئ ماته ځکه ژغورلي مې یئ تاسو»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_22.mp3', '', 1761754199, 1761754199),
(49926, 'Isaiah 44:23', 'Isaiah', 44, 23, 'ای اسمانونو، سندرې ووایئ د خوشحالۍ ځکه چې وکړل څښتن لوی کارونه! ای د ځمکې ژورو ځایونو، ووهئ چیغې د خوشحالۍ ای غرونو او ای ټولو ونو د ځنګل ووایئ د خوشحالۍ سندرې! ځکه چې وژغوره څښتن د یعقوب قوم او اسراییل به وکړي ثنا او صفت د څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_23.mp3', '', 1761754199, 1761754199),
(49927, 'Isaiah 44:24', 'Isaiah', 44, 24, 'څښتن، ژغورونکی ستا داسې وایي: چا چې ته جوړ کړې د مور ګېډه کې هغه داسې وایي: «زه یم څښتن او یم خالق د ټولو شیانو ما خپاره کړل اسمانونه په یوازې ځان او په خپله مې هواره کړله ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_24.mp3', '', 1761754199, 1761754199),
(49928, 'Isaiah 44:25', 'Isaiah', 44, 25, 'باطلوم زه پېشګویۍ د فال کتونکو زه د هغوی نه احمقان جوړوم ثابتوم غلطې د هوښیارانو وینا او د هغوی حکمت بدلوم په حماقت باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_25.mp3', '', 1761754199, 1761754199),
(49929, 'Isaiah 44:26', 'Isaiah', 44, 26, 'خو چې کله پېشګویي کړي خدمتګار زما او کله چې ولېږمه زه استازي چې ښکاره کړي نقشې زما تاییدوم د خپل خادم خبرې او عملي کومه نقشې د استازو خپلو د اورشلیم په اړه وایمه زه چې هغه به بیا وګرځي استوګنځی یوځل به بیا اباد شي د یهودا ښارونه او کنډوالې به یې کړم جوړې بېرته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_26.mp3', '', 1761754199, 1761754199),
(49930, 'Isaiah 44:27', 'Isaiah', 44, 27, 'ژور بحر ته زه وایمه چې وچ شه او هم به وچ کړمه سیندونه ستاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_27.mp3', '', 1761754199, 1761754199),
(49931, 'Isaiah 44:28', 'Isaiah', 44, 28, 'د کوروش په اړه وایمه زه: ‹هغه زما شپوندی او لارښود دی زما د قوم او کړي به ټول هغه کارونه چې ترې غواړم یې زه هغه به حکم وکړي چې باید جوړ شي اورشلیم او باید کېښودل شي زما د سپېڅلي کور بنیاد›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_28.mp3', '', 1761754199, 1761754199),
(49932, 'Job 21:1', 'Job', 21, 1, 'بيا ايُوب جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_1.mp3', '', 1761754199, 1761754199),
(49933, 'Job 21:2', 'Job', 21, 2, '”زما خبرې په غور سره واورئ، او دا دې تاسو له تسلى درکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_2.mp3', '', 1761754199, 1761754199),
(49934, 'Job 21:3', 'Job', 21, 3, 'ما پرېږدئ چې خبرې وکړم، او چې خبرې ختمې کړم نو بيا تاسو داړې چينګولے شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_3.mp3', '', 1761754199, 1761754199),
(49935, 'Job 21:4', 'Job', 21, 4, 'زما شکايت د خُدائ پاک نه دے د انسانانو نه نۀ دے. او د دې بې‌صبرۍ ما سره ښۀ سبب شته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_4.mp3', '', 1761754199, 1761754199),
(49936, 'Job 21:5', 'Job', 21, 5, 'ما ته وګورئ او حېران شئ، او ګوته په خولۀ کښې ونيسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_5.mp3', '', 1761754199, 1761754199),
(49937, 'Job 21:6', 'Job', 21, 6, 'کله چې زۀ په دې سوچ وکړم نو خفه شم، او زما په بدن لړزان راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_6.mp3', '', 1761754199, 1761754199),
(49938, 'Job 21:7', 'Job', 21, 7, 'بدعمله خلق ولې ژوندى وى، او پوخ عُمر ته ورسيږى او طاقتور شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_7.mp3', '', 1761754199, 1761754199),
(49939, 'Job 21:8', 'Job', 21, 8, 'د هغوئ بچى د هغوئ په وړاندې ودان شى، او د هغوئ نمسى د هغوئ په موجودګۍ کښې آباد شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_8.mp3', '', 1761754199, 1761754199),
(49940, 'Job 21:9', 'Job', 21, 9, 'د هغوئ کورونه د يرې نه بچ وى، او خُدائ پاک هغوئ له سزا نۀ ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_9.mp3', '', 1761754199, 1761754199),
(49941, 'Job 21:10', 'Job', 21, 10, 'د هغوئ غوَيے په مال کولو کښې هيڅکله نۀ ناکامه کيږى، د هغوئ غوا بچى راوړى او يو هم نۀ ضائع کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_10.mp3', '', 1761754199, 1761754199),
(49942, 'Job 21:11', 'Job', 21, 11, 'د هغوئ ماشومان د رَمو په شان ګرځى، او د هغوئ بچى د خوشحالۍ نه ګډيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_11.mp3', '', 1761754199, 1761754199),
(49943, 'Job 21:12', 'Job', 21, 12, 'هغوئ د تمبل او د رباب سره سندرې وائى، او د شپېلۍ د آواز سره خوشحالى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_12.mp3', '', 1761754199, 1761754199),
(49944, 'Job 21:13', 'Job', 21, 13, 'هغوئ په مالدارۍ کښې وخت تېروى، او په خېر سره قبر ته ځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_13.mp3', '', 1761754199, 1761754199),
(49945, 'Job 21:14', 'Job', 21, 14, 'هغوئ خُدائ پاک ته وائى چې مونږ پرېږده. زمونږ زړۀ نۀ غواړى چې ستا تابعدارى وکړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_14.mp3', '', 1761754199, 1761754199),
(49946, 'Job 21:15', 'Job', 21, 15, 'قادر خُدائ څوک دے، چې مونږ د هغۀ خِدمت وکړُو؟ او مونږ ته به څۀ فائده راورسيږى چې مونږ هغۀ ته سوال وکړُو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_15.mp3', '', 1761754199, 1761754199),
(49947, 'Job 21:16', 'Job', 21, 16, 'خو هغوئ په خپل محنت سره نۀ دى مالداره شوى، د بدعمله کسانو مشوره ما ته منظوره نۀ ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_16.mp3', '', 1761754199, 1761754199),
(49948, 'Job 21:17', 'Job', 21, 17, 'د بدعمله خلقو ډيوه څو ځلې مړه کړے شوې وه؟ او څو ځلې په هغوئ باندې تباهى راغلې وه. خُدائ پاک څو ځلې په خپله غصه کښې سزا ورکوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_17.mp3', '', 1761754199, 1761754199),
(49949, 'Job 21:18', 'Job', 21, 18, 'هغوئ څو ځلې د هوا په مخکښې د خسڼى په شان شول، او څو ځلې د بوسو په شان طوفان يوړل؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_18.mp3', '', 1761754199, 1761754199),
(49950, 'Job 21:19', 'Job', 21, 19, 'تۀ وائې چې، خُدائ پاک د هغوئ په وجه د هغوئ بچو له سزا ورکوى. نو دا سزا دې هم هغوئ له ورکړے شى، چې پته ورته ولګى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_19.mp3', '', 1761754199, 1761754199),
(49951, 'Job 21:20', 'Job', 21, 20, 'هغوئ دې په خپلو سترګو خپله تباهى وګورى، او د قادر خُدائ غصه دې تېره کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_20.mp3', '', 1761754199, 1761754199),
(49952, 'Job 21:21', 'Job', 21, 21, 'دا ځکه چې کله هغوئ مړۀ شى نو دا فکر به ورسره نۀ وى چې په خاندان يې څۀ کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_21.mp3', '', 1761754199, 1761754199),
(49953, 'Job 21:22', 'Job', 21, 22, 'څوک خُدائ پاک ته ښودنه کولے شى، هغه خُدائ پاک ته چې د غټو مرتبو لرونکو خلقو هم عدالت کوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_22.mp3', '', 1761754199, 1761754199),
(49954, 'Job 21:23', 'Job', 21, 23, 'څوک چې ښۀ په مالدارۍ کښې مړ شى، هغه په آرام او حِفاظت کښې وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_23.mp3', '', 1761754199, 1761754199),
(49955, 'Job 21:24', 'Job', 21, 24, 'هغوئ ښۀ صحتمند وى، او ښۀ غټ او تکړه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_24.mp3', '', 1761754199, 1761754199),
(49956, 'Job 21:25', 'Job', 21, 25, 'بل کس په سخته غريبۍ کښې مړ شى، او هيڅکله يې ښۀ ورځ نۀ وى ليدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_25.mp3', '', 1761754199, 1761754199),
(49957, 'Job 21:26', 'Job', 21, 26, 'هغوئ ټول يو شان مرى او په خاورو کښې ښخيږى، او هغوئ ټول د چينجو خوراک شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_26.mp3', '', 1761754199, 1761754199),
(49958, 'Job 21:27', 'Job', 21, 27, 'ګوره، ما ته ستا د سوچونو پته ده، او ما ته زما خِلاف ستا د منصوبو پته ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_27.mp3', '', 1761754199, 1761754199),
(49959, 'Job 21:28', 'Job', 21, 28, 'تۀ به ما ته د مالدارو او بدعمله خلقو په حقله ووائى، د چا کورونه چې د هغوئ د ګناهونو په وجه تباه شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job21_verse_28.mp3', '', 1761754199, 1761754199),
