(49966, 'Genesis 24:1', 'Genesis', 24, 1, 'ابراهیم ډېر زوړ شوی ؤ او څښتن هغه ته په هر کار کې برکت ورکاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_1.mp3', '', 1761754199, 1761754199),
(49967, 'Genesis 24:2', 'Genesis', 24, 2, 'ابراهیم خپل ناظر ته چې د هغه په کورنۍ کې د هرڅه واکدار ؤ، وویل: «خپل لاس دې زما د ورون لاندې کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_2.mp3', '', 1761754199, 1761754199),
(49968, 'Genesis 24:3', 'Genesis', 24, 3, 'په دې ډول زه د څښتن یعنې د اسمانونو او ځمکې د خدای په نوم قسم درکوم چې زما زوی ته به په دې ځای یعنې د کنعان په خلکو کې ښځه نه کوې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_3.mp3', '', 1761754199, 1761754199),
(49969, 'Genesis 24:4', 'Genesis', 24, 4, 'بلکې زما وطن او زما خپلو خپلوانو ته لاړ شه او هلته زما زوی اسحاق ته ښځه وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_4.mp3', '', 1761754199, 1761754199),
(49970, 'Genesis 24:5', 'Genesis', 24, 5, 'ناظر پوښتنه وکړه: «که چېرې انجلۍ ونه غواړي چې خپل کور پرېږدي او زما سره دې وطن ته راشي، نو بیا به څنګه کیږي؟ ایا ستا زوی بېرته هغه وطن ته بوځم چې ته ورڅخه راوتلی یې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_5.mp3', '', 1761754199, 1761754199),
(49971, 'Genesis 24:6', 'Genesis', 24, 6, 'ابراهیم ځواب ورکړ: «پام کوه چې زما زوی به بېرته هلته نه بیایې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_6.mp3', '', 1761754199, 1761754199),
(49972, 'Genesis 24:7', 'Genesis', 24, 7, 'څښتن د اسمانونو خدای زه د خپل پلار د کور او اصلي وطن څخه راوویستلم او زما سره یې قسم وخوړ چې دا وطن به ستا اولادې ته ورکوم. هغه به خپله فرښته ستا څخه مخکې ولېږي، ترڅو ته وکولای شې چې په هغه ځای کې زما زوی ته ښځه وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_7.mp3', '', 1761754199, 1761754199),
(49973, 'Genesis 24:8', 'Genesis', 24, 8, 'که چېرې هغه انجلۍ په دې رضا نه شي چې ستا سره راشي، نو ته به د هغه قسم څخه چې زما سره دې کړی دی، خلاص یې. خو په هېڅ حالت کې به زما زوی هلته نه ورولې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_8.mp3', '', 1761754199, 1761754199),
(49974, 'Genesis 24:9', 'Genesis', 24, 9, 'نو ناظر خپل لاس د خپل بادار د ورون لاندې کېښود او قسم یې وخوړ چې څه چې ابراهیم د هغه څخه غواړي هغه به وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_9.mp3', '', 1761754199, 1761754199),
(49975, 'Genesis 24:10', 'Genesis', 24, 10, 'ناظر د خپل بادار له اوښانو څخه لس اوښان او هر ډول ښه شیان د ځان سره واخیستل او د بین‌النهرین شمال ته هغه ښار ته لاړ چې ناحور په کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_10.mp3', '', 1761754199, 1761754199),
(49976, 'Genesis 24:11', 'Genesis', 24, 11, 'هغه مازدیګر، یعنې کله چې ښځې د اوبو د راوړلو دپاره راوتلې، هلته ورسېده او خپل اوښان یې د ښار څخه دباندې د څاه په غاړه ګونډه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_11.mp3', '', 1761754199, 1761754199),
(49977, 'Genesis 24:12', 'Genesis', 24, 12, 'بیا هغه دعا وکړه: «ای څښتنه، زما د بادار ابراهیم خدایه! نن ما بریالی کړه او زما د بادار ابراهیم سره خپله وعده پوره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_12.mp3', '', 1761754199, 1761754199),
