(49981, 'Genesis 24:16', 'Genesis', 24, 16, 'هغه یوه ډېره ښکلې انجلۍ وه او پېغله وه. هغه څاه ته ورښکته شوه، خپل منګی یې د اوبو څخه ډک کړ او بېرته راپورته شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_16.mp3', '', 1761754199, 1761754199),
(49982, 'Genesis 24:17', 'Genesis', 24, 17, 'ناظر د هغې د لیدلو دپاره په منډه ورغی او ویې ویل: «مهرباني وکړه د خپل منګي څخه لږې اوبه ماته راکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_17.mp3', '', 1761754199, 1761754199),
