(49995, 'Genesis 24:30', 'Genesis', 24, 30, 'لابان د خپلې خور ربکا په پوزه پېزوان او په لاسونو باندې کړۍ‌ګانې ولیدلې او د هغې څخه یې هغه خبرې واورېدلې چې هغه سړي ورته کړې وې. نو دی ورغی او ویې لیدل چې د ابراهیم ناظر د څاه په غاړه د اوښانو سره ولاړ دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_30.mp3', '', 1761754199, 1761754199),
(49996, 'Genesis 24:31', 'Genesis', 24, 31, 'هغه وویل: «زما سره کور ته راشه. ته داسې سړی یې چې څښتن درته برکت درکړی دی. ولې دباندې ولاړ یې؟ ما ستا دپاره په خپل کور کې کوټه او ستا د اوښانو دپاره ځای تیار کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_31.mp3', '', 1761754199, 1761754199),
