(50003, 'Genesis 24:38', 'Genesis', 24, 38, 'بلکې زما د پلار کورنۍ او زما خپلې قبیلې ته لاړ شه او زما زوی ته ښځه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_38.mp3', '', 1761754199, 1761754199),
(50004, 'Genesis 24:39', 'Genesis', 24, 39, 'بیا ما د خپل بادار څخه پوښتنه وکړه: ‹که چېرې انجلۍ زما سره رانه شي، نو بیا څه وکړم؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_39.mp3', '', 1761754199, 1761754199),
(50005, 'Genesis 24:40', 'Genesis', 24, 40, 'هغه ځواب راکړ: ‹هغه څښتن چې زه یې پیروي کوم هغه به خپله فرښته ستا سره ولېږي او ستا سفر به بریالی کړي، ترڅو ته وکولای شې چې زما زوی ته زما د خپلې قبیلې او زما د پلار د کورنۍ څخه ښځه وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_40.mp3', '', 1761754199, 1761754199),
(50006, 'Genesis 24:41', 'Genesis', 24, 41, 'کله چې ته زما قبیلې ته ورشې، نو زما د قسم څخه به خلاص شې، حتی که هغوی د انجلۍ د درکولو څخه انکار هم وکړي، ته به زما د قسم څخه خلاص یې.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_41.mp3', '', 1761754199, 1761754199),
(50007, 'Genesis 24:42', 'Genesis', 24, 42, 'کله چې نن زه څاه ته راغلم، ما وویل: ‹ای څښتنه، زما د بادار ابراهیم خدایه! که ستا رضا وي، نو ماته په دې سفر کې چې راغلی یم بری راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_42.mp3', '', 1761754199, 1761754199),
(50008, 'Genesis 24:43', 'Genesis', 24, 43, 'دا دی زه دلته د دې څاه په غاړه ولاړ یم. نو داسې دې وشي چې کومه انجلۍ چې د اوبو د وړلو دپاره راځي، نو زه به د هغې څخه وغواړم چې د خپل منګي څخه ماته لږې اوبه راکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_43.mp3', '', 1761754199, 1761754199),
(50009, 'Genesis 24:44', 'Genesis', 24, 44, 'که چېرې هغه راته ووایي چې وڅښه او زه به ستا د اوښانو دپاره هم اوبه راوباسم، نو دا دې هماغه انجلۍ وي چې څښتن زما د بادار د زوی دپاره غوره کړې ده.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_44.mp3', '', 1761754199, 1761754199),
(50010, 'Genesis 24:45', 'Genesis', 24, 45, 'مخکې له دې چې زما دعا خلاصه شي، ربکا د خپل منګي سره چې په اوږو یې ایښی ؤ، راغله. هغه څاه ته ښکته شوه او اوبه یې راوویستلې او ما هغې ته وویل: ‹لږې اوبه راکړه چې زه یې وڅښم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_45.mp3', '', 1761754199, 1761754199);